#!/usr/bin/env python3
"""Generate src/runtime/stubs.cpp: one logging stub per unsupported export.

Each stub is __cdecl (caller cleans the stack), so it is safe whatever the
real argument list is, and logs its name once so unsupported calls show up
in pxvk-runtime logs. The export names come from src/runtime/exports.def.
"""
import re
from pathlib import Path

root = Path(__file__).resolve().parent.parent
names = re.findall(r"^\s+(cu\w+)=pxvkNotSupportedStub", (root / "src/runtime/exports.def").read_text(), re.M)
lines = [
    "// Generated by tools/gen-stubs.py from src/runtime/exports.def. Do not edit.",
    '#include "cuda_abi.h"',
    "",
    "void pxvk_log_unsupported(const char *name);",
    "",
]
for name in names:
    lines.append(f'extern "C" CUresult __cdecl pxvk_stub_{name}(void)')
    lines.append("{")
    lines.append(f'    pxvk_log_unsupported("{name}");')
    lines.append("    return CUDA_ERROR_NOT_SUPPORTED;")
    lines.append("}")
(root / "src/runtime/stubs.cpp").write_text("\n".join(lines) + "\n")
definition = ["LIBRARY nvcuda", "EXPORTS"] + [f"    {n}=pxvk_stub_{n}" for n in names]
(root / "src/runtime/exports.def").write_text("\n".join(definition) + "\n")
print(f"{len(names)} stubs")
